(1, '2025-011', 'Advocacy Dri fit t-shirt', '24-1759', 'Department of Health - CAR Office', '25-01-0022', 'AXN ENTERPRISES', 'Unit 4C #96, Imelda Village, Baguio City', 'Advocacy materials for the conduct of Regional, Provincial and the academe of various mental health and suicide prevention activities: Dri Fit T-shirt \r\n- 100% Polyester, breathable. V-Neck, individually packed in clear plastic with sizes indicated.\r\n-Various Sizes: Medium (67pcs) and Large (40 pcs) only\r\n4 inch logo in back, design c/o HEPOs:', NULL, NULL, 17, 155.00, 1, 1, 31, 107, 4, NULL, NULL, NULL),
(2, '2025-1040', 'DOH-Vest', '24-1861', 'Department of Health - CAR Office', '25-01-0012', 'NUJ PRINTING SERVICES', '405 A LA AZOTEA BLDG. SESSION RD. BAGUIO CITY', 'DOH VEST\r\nDetails:\r\n-Safe radial Light vest\r\n-Comforatable and light weight to wear\r\n-Breathable to wear + breathable mesh quick-drying thin material\r\n-Loose V-neck design\r\n-Soft and comfortable to touch\r\n-COLOR: Navy Blue with navy blue zipper\r\n-Silk screen printing (white color) - big printed DOH under the DOH is Department of Health Cordillera Administrative Region (at the back area)\r\n-In front DOH LOGO- left side computerized patch; Size: Ht - 4 inches; Width 4 inches\r\n-In front Breastfdeeding tsek logo computerized embroidered patch- right side;\r\n Size: Ht 4 inches; width- 4 inches\r\nPocket: Infront of vest five (6) pockets\r\n-4 (four) pockets with magic snap upper part of teh vest\r\n2 (two) pockets with zipper, sewn on the center of the vest\r\n-heavy duty nylon zipper, sewn on the center of the vest with accessories\r\nThe size shall ve sewn at the back of the neck sizes:\r\nMedium- 50 pcs\r\nLarge- 40pcs\r\nX-Large- 20 pcs-Packaging: individually packed with plastic, 10 pieces per bundle, 10 bundles epr corrugated carton\r\n', NULL, NULL, 17, 395.00, 1, 1, 31, 110, 4, NULL, NULL, NULL),
(3, '2025-0010', 'Poster-full color chrome coat', '24-1619', 'Department of Health - CAR Office', '25-01-0020', 'GOLD INK PRINTING SHOP', 'G/F, Stall No.3, Juniper Bldg., Bonifacio St., ABCR Baguio City', 'Poster of various kinds, size 18\"x24\", full color, Chrome Coat #189, 2 kinds, 1000pcs per kind, packed per kind by 100s', NULL, NULL, 17, 19.44, 1, 1, 13, 2000, 4, NULL, NULL, NULL),
(4, '2025-1477', 'Customized Back Pack for BHW', '24-1743', 'Department of Health - CAR Office', '25-01-0010', 'QUEBY ENTERPRISES', 'Km 92 Bitas, Arayat, Pampanga', 'CUSTOMIZED BACKPACK FOR BHW\r\n With laptop pouch, holds up to 17\" laptop, wit large internal storage up to 25L capacity,\r\n', NULL, NULL, 12, 895.00, 1, 1, 16, 500, 4, NULL, NULL, NULL),
(5, '2025-0002', 'Token for Shield Initiative-t-shirt', '24-1903', 'Department of Health - CAR Office', '25-01-0002', 'LASER MARKETING', 'Unit 4C #96, Imelda Village, Baguio City ', 'TOKEN FOR SHIELD INITIATIVE\r\nT-shirt\r\nDri-Fit Fabric (Polyester bird eye mesh sport fabric)\r\n', NULL, NULL, 17, 488.00, 1, 1, 30, 300, 4, NULL, '2025-01-03', NULL),
